<div x-data="globalSearch()" x-on:focus-search.window="$refs.input.focus()" class="relative w-full max-w-xl"><form method="GET" action="{{ route('search') }}" class="relative" role="search"><x-icon name="search" class="pointer-events-none absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-slate-400" /><input x-ref="input" x-model="query" x-on:input.debounce.250ms="suggest" type="search" name="q" value="{{ request()->routeIs('search') ? request('q') : '' }}" placeholder="Search projects, tasks, people…" class="form-input border-slate-200 bg-slate-100/70 pl-9 shadow-none focus:bg-white"></form><div x-show="open" x-cloak x-on:click.outside="open = false" class="absolute left-0 right-0 top-12 z-50 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-xl"><template x-for="group in groups" :key="group.key"><div class="border-b border-slate-100 p-2 last:border-0"><p class="px-2 py-1 text-[11px] font-semibold uppercase tracking-wide text-slate-400" x-text="group.label"></p><template x-for="item in group.items" :key="item.id"><a :href="item.url" class="block rounded-lg px-2 py-2 hover:bg-slate-50"><p class="truncate text-sm font-medium text-slate-800" x-text="item.title"></p><p class="truncate text-xs text-slate-500" x-text="item.subtitle"></p></a></template></div></template><p x-show="query && !groups.length" class="p-4 text-sm text-slate-500">No matches.</p></div></div>
